//! Import -> edit -> export fidelity over LibreOffice-authored `.docx`/`.odt` fixtures
//! (`crates/doc/fixtures/lo-*.{docx,odt}`, regenerated by `fixtures/src/regenerate.sh`).
//!
//! Every fixture is imported, edited through the model (a paragraph's text changes and a new
//! paragraph is inserted), exported and re-imported. The checks:
//! - every package part of the original is still in the export;
//! - the regenerated body (`word/document.xml` / `content.xml`) is namespace-well-formed and
//!   keeps every unmodeled construct of the original (element census per kind);
//! - re-importing the export yields the edited model again.

use quick_xml::events::Event;
use quick_xml::name::ResolveResult;
use std::collections::{BTreeMap, BTreeSet};
use std::io::Read as _;
use tilo_doc::{AttrVal, DocSnapshot, Document};
use tilo_doc_codecs::preserve::is_codec_private_attr;
use tilo_doc_codecs::{DocxCodec, FormatProvider, OdtCodec};

const EDIT_SUFFIX: &str = " (edited)";
const INSERTED: &str = "Inserted by the fidelity test.";

