fn unzip(bytes: &[u8]) -> BTreeMap<String, Vec<u8>> {
    let mut z = zip::ZipArchive::new(std::io::Cursor::new(bytes)).expect("zip");
    let mut out = BTreeMap::new();
    for i in 0..z.len() {
        let mut f = z.by_index(i).expect("entry");
        if f.is_dir() {
            continue;
        }
        let mut buf = Vec::new();
        f.read_to_end(&mut buf).expect("read entry");
        out.insert(f.name().unwrap().into_owned(), buf);
    }
    out
}

/// Element-name counts of an XML part, restricted to `kinds`.
fn census(xml: &[u8], kinds: &[&str]) -> BTreeMap<String, usize> {
    let mut reader = quick_xml::Reader::from_reader(xml);
    let mut out: BTreeMap<String, usize> = kinds.iter().map(|k| ((*k).to_string(), 0)).collect();
    let mut buf = Vec::new();
    loop {
        match reader.read_event_into(&mut buf).expect("well-formed XML") {
            Event::Start(e) | Event::Empty(e) => {
                let name = String::from_utf8_lossy(e.name().as_ref()).into_owned();
                if let Some(n) = out.get_mut(&name) {
                    *n = n.saturating_add(1);
                }
            }
            Event::Eof => break,
            _ => {}
        }
        buf.clear();
    }
    out
}

/// The non-blank text nodes of an XML part, in document order.
fn text_nodes(xml: &[u8]) -> Vec<String> {
    let mut reader = quick_xml::Reader::from_reader(xml);
    let mut out = Vec::new();
    let mut buf = Vec::new();
    loop {
        match reader.read_event_into(&mut buf).expect("well-formed XML") {
            Event::Text(t) => {
                let t = t.xml10_content().expect("text").trim().to_string();
                if !t.is_empty() {
                    out.push(t);
                }
            }
            Event::Eof => break,
            _ => {}
        }
        buf.clear();
    }
    out
}

/// Parse `xml` resolving every element and attribute prefix; an error names the first
/// undeclared prefix or the parse failure.
fn namespace_well_formed(xml: &[u8]) -> Result<(), String> {
    let mut reader = quick_xml::NsReader::from_reader(xml);
    let mut buf = Vec::new();
    loop {
        let (res, ev) = reader
            .read_resolved_event_into(&mut buf)
            .map_err(|e| format!("malformed XML: {e}"))?;
        match ev {
            Event::Start(ref e) | Event::Empty(ref e) => {
                let name = String::from_utf8_lossy(e.name().as_ref()).into_owned();
                if let ResolveResult::Unknown(p) = res {
                    return Err(format!(
                        "undeclared prefix {:?} on <{name}>",
                        String::from_utf8_lossy(&p)
                    ));
                }
                for a in e.attributes() {
                    let a = a.map_err(|e| format!("bad attribute on <{name}>: {e}"))?;
                    if let (ResolveResult::Unknown(p), _) =
                        reader.resolver().resolve_attribute(a.key)
                    {
                        return Err(format!(
                            "undeclared attribute prefix {:?} on <{name}>",
                            String::from_utf8_lossy(&p)
                        ));
                    }
                }
            }
            Event::Eof => return Ok(()),
            _ => {}
        }
        buf.clear();
    }
}

/// Import `bytes`, keeping the binary content the file embeds in `content` (as an app would).
fn import(
    codec: &dyn FormatProvider,
    bytes: &[u8],
    what: &str,
    content: &tilo_content::ContentStore,
) -> Document {
    let mut d = Document::new();
    let mut inputs = tilo_content::ContentInputs::new();
    codec
        .import(bytes, &mut d.as_mut(), &mut inputs)
        .unwrap_or_else(|e| panic!("{what}: import failed: {e}"));
    content
        .put_inputs(&inputs)
        .unwrap_or_else(|e| panic!("{what}: keeping the file's binary content failed: {e}"));
    d
}

/// Edit through the model: append to the last non-empty paragraph and insert a new paragraph
/// after the first heading (or at the start).
fn edit(d: &mut Document, what: &str) {
    let snap = d.materialize();
    let last = snap
        .blocks
        .iter()
        .rev()
        .find(|b| b.kind == "paragraph" && !b.text.is_empty())
        .unwrap_or_else(|| panic!("{what}: no paragraph to edit"));
    let len = last.text.chars().count();
    d.splice_text(&last.id, len, 0, EDIT_SUFFIX);
    let anchor = snap
        .blocks
        .iter()
        .find(|b| b.kind == "heading")
        .map(|b| b.id.clone());
    let id = d.insert_block(anchor.as_deref(), "paragraph");
    d.splice_text(&id, 0, 0, INSERTED);
}

/// A comparable view of a snapshot: block kinds, texts, marks (with values) and the attrs that
/// are not import-order ids.
type Norm = Vec<(
    String,
    String,
    Vec<(usize, usize, String, String)>,
    Vec<(String, String)>,
)>;

fn norm(snap: &DocSnapshot) -> Norm {
    snap.blocks
        .iter()
        .map(|b| {
            let mut marks: Vec<_> = b
                .marks
                .iter()
                .map(|m| {
                    // Note/comment/change ids are minted per import; compare by presence only.
                    let value = match m.name.as_str() {
                        "note-ref" | "comment" | "ins" | "del" => String::new(),
                        _ => format!("{:?}", m.value),
                    };
                    (m.start, m.end, m.name.clone(), value)
                })
                .collect();
            marks.sort();
            marks.dedup();
            // Codec-private attrs (kept markup, original ids) are the codec's to rewrite; what
            // they carry is checked through the element census instead.
            let attrs = b
                .attrs
                .iter()
                .filter(|(k, _)| k.as_str() != "table" && !is_codec_private_attr(k))
                .filter(|(k, v)| {
                    // The final section properties are rebuilt around the header/footer.
                    !(k.as_str() == "xml"
                        && matches!(v, AttrVal::Str(x) if x.starts_with("<w:sectPr")))
                })
                .map(|(k, v)| {
                    let v = match v {
                        AttrVal::Str(s) => s.clone(),
                        other => format!("{other:?}"),
                    };
                    (k.clone(), v)
                })
                .collect();
            (b.kind.clone(), b.text.clone(), marks, attrs)
        })
        .collect()
}

/// Page-region content: the parts holding headers and footers (every docx header/footer part;
/// the ODF master pages live in styles.xml), and the constructs to count in them.
struct Regions {
    parts: fn(&str) -> bool,
    kinds: &'static [&'static str],
}

const DOCX_REGIONS: Regions = Regions {
    parts: |name| {
        let file = name.rsplit('/').next().unwrap_or(name);
        (file.starts_with("header") || file.starts_with("footer"))
            && std::path::Path::new(file)
                .extension()
                .is_some_and(|e| e.eq_ignore_ascii_case("xml"))
    },
    kinds: &[
        "w:fldSimple",
        "w:fldChar",
        "w:instrText",
        "w:drawing",
        "w:tbl",
        "w:p",
    ],
};

const ODT_REGIONS: Regions = Regions {
    parts: |name| name == "styles.xml",
    kinds: &[
        "style:header",
        "style:footer",
        "text:page-number",
        "text:page-count",
        "text:date",
        "text:title",
        "draw:frame",
    ],
};

/// Summed element census and text nodes of the region parts of a package.
fn region_census(
    parts: &BTreeMap<String, Vec<u8>>,
    regions: &Regions,
) -> (BTreeMap<String, usize>, String) {
    let mut total: BTreeMap<String, usize> = BTreeMap::new();
    let mut text = String::new();
    for (_, bytes) in parts.iter().filter(|(name, _)| (regions.parts)(name)) {
        for (k, n) in census(bytes, regions.kinds) {
            let slot = total.entry(k).or_default();
            *slot = slot.saturating_add(n);
        }
        text.push_str(&text_nodes(bytes).concat());
    }
    (total, text)
}

/// (a) Every original part survives (renamed regenerated parts are listed per format), a part
/// the codec does not write comes back byte for byte, and one it merges the model into keeps
/// every definition of the original.
fn check_parts(
    what: &str,
    original: &BTreeMap<String, Vec<u8>>,
    exported: &BTreeMap<String, Vec<u8>>,
    regenerated: &[&str],
    problems: &mut Vec<String>,
) {
    let missing: Vec<&String> = original
        .keys()
        .filter(|k| !exported.contains_key(*k) && !regenerated.contains(&k.as_str()))
        .collect();
    if !missing.is_empty() {
        problems.push(format!("{what}: parts dropped on export: {missing:?}"));
    }
    // A part the codec does not write itself comes back byte for byte.
    let changed: Vec<&String> = original
        .iter()
        .filter(|(name, bytes)| {
            !rewritten(name) && exported.get(*name).is_some_and(|out| out != *bytes)
        })
        .map(|(name, _)| name)
        .collect();
    if !changed.is_empty() {
        problems.push(format!(
            "{what}: carried parts changed on export: {changed:?}"
        ));
    }
    // A part the codec merges the model into keeps every definition of the original.
    for (part, element, attr) in MERGED_DEFINITIONS {
        let (Some(before), Some(after)) = (original.get(*part), exported.get(*part)) else {
            continue;
        };
        let after = attr_values(after, element, attr);
        let lost: Vec<String> = attr_values(before, element, attr)
            .into_iter()
            .filter(|v| !after.contains(v))
            .collect();
        if !lost.is_empty() {
            problems.push(format!("{what}: {part} lost {element} {attr}s {lost:?}"));
        }
    }
}

/// The kinds counted fewer times `after` than `before`, as `kind: before -> after`.
fn lost_counts(before: &BTreeMap<String, usize>, after: &BTreeMap<String, usize>) -> Vec<String> {
    before
        .iter()
        .filter(|(k, n)| after.get(*k).copied().unwrap_or(0) < **n)
        .map(|(k, n)| format!("{k}: {n} -> {}", after.get(k).copied().unwrap_or(0)))
        .collect()
}

/// The model shows what `LibreOffice` shows of kept inline elements (`shows`), and the exporters
/// that cannot keep them print their text but never their placeholder.
fn check_shown_text(what: &str, snap: &DocSnapshot, shows: &[&str], problems: &mut Vec<String>) {
    let text: Vec<&str> = snap.blocks.iter().map(|b| b.text.as_str()).collect();
    let text = text.join("\n");
    for line in shows {
        if !text.contains(line) {
            problems.push(format!("{what}: the model does not show {line:?}"));
        }
    }
    let html = tilo_doc_codecs::export_html::render_html(
        snap,
        tilo_doc_codecs::export_html::HtmlOptions::default(),
        &tilo_content::NoContent,
    );
    let rtf = tilo_doc_codecs::export_rtf::render_rtf(snap);
    let md = String::from_utf8(tilo_doc_codecs::markdown::export_views(
        &snap.properties,
        &snap.blocks,
        &snap.notes,
    ))
    .expect("utf-8");
    // HTML and RTF have no notes and print a note reference's placeholder; any placeholder
    // beyond those stands for a kept element.
    let note_refs = snap
        .blocks
        .iter()
        .flat_map(|b| &b.marks)
        .filter(|m| m.name == tilo_doc::schema::MARK_NOTE_REF)
        .count();
    for (format, out) in [("html", &html), ("rtf", &rtf), ("md", &md)] {
        let placeholders = out.matches(tilo_doc::schema::FIELD_PLACEHOLDER).count();
        if placeholders > note_refs {
            problems.push(format!(
                "{what}: {format} export prints {placeholders} placeholders for {note_refs} note references"
            ));
        }
        for line in shows {
            let words = line.split_whitespace().next().unwrap_or_default();
            if !out.contains(words) {
                problems.push(format!("{what}: {format} export lacks {words:?}"));
            }
        }
    }
}

fn check_fixture(
    codec: &dyn FormatProvider,
    fx: &Fixture,
    body_part: &str,
    kinds: &[&str],
    regenerated: &[&str],
    regions: &Regions,
    problems: &mut Vec<String>,
) {
    let what = fx.name;
    let original = unzip(fx.bytes);
    let content = tilo_content::ContentStore::memory();
    let mut d = import(codec, fx.bytes, what, &content);
    check_shown_text(what, &d.materialize(), fx.shows, problems);
    edit(&mut d, what);
    let edited = d.materialize();
    let out = codec
        .export(d.as_ref(), &content)
        .unwrap_or_else(|e| panic!("{what}: export failed: {e}"));
    let exported = unzip(&out);
    // Hand the export to an outside check (LibreOffice re-opening it, see
    // `fixtures/src/regenerate.sh --check`) when asked to.
    if let Some(dir) = std::env::var_os("QDOC_FIDELITY_OUT") {
        let path = std::path::Path::new(&dir).join(format!("edited-{what}"));
        std::fs::write(&path, &out).unwrap_or_else(|e| panic!("{}: {e}", path.display()));
    }

    check_parts(what, &original, &exported, regenerated, problems);

    // (b) The regenerated body is well-formed and keeps every unmodeled construct.
    let body_in = original.get(body_part).expect("original body part");
    let body_out = exported.get(body_part).expect("exported body part");
    if let Err(e) = namespace_well_formed(body_out) {
        problems.push(format!("{what}: exported {body_part}: {e}"));
        return;
    }
    let before = census(body_in, kinds);
    let after = census(body_out, kinds);
    let lost = lost_counts(&before, &after);
    if !lost.is_empty() {
        problems.push(format!(
            "{what}: unmodeled constructs lost on export: {lost:?}"
        ));
    }
    // Headers and footers keep their fields and text.
    let (regions_in, region_text_in) = region_census(&original, regions);
    let (regions_out, region_text_out) = region_census(&exported, regions);
    let lost = lost_counts(&regions_in, &regions_out);
    if !lost.is_empty() || !region_text_out.contains(region_text_in.trim()) {
        problems.push(format!(
            "{what}: header/footer content lost: {lost:?}; text {region_text_in:?} -> {region_text_out:?}"
        ));
    }

    // Every piece of text of the original body is still somewhere in the exported body.
    let exported_text = text_nodes(body_out).concat();
    let dropped: Vec<String> = text_nodes(body_in)
        .into_iter()
        .filter(|t| !exported_text.contains(t.as_str()))
        .collect();
    if !dropped.is_empty() {
        problems.push(format!("{what}: body text dropped on export: {dropped:?}"));
    }
    let body_text = String::from_utf8_lossy(body_out);
    if !(body_text.contains(INSERTED) && body_text.contains(EDIT_SUFFIX.trim())) {
        problems.push(format!(
            "{what}: the edit is missing from the exported body"
        ));
    }

    // (c) Re-import yields the edited model.
    let again = import(codec, &out, &format!("{what} (re-import)"), &content).materialize();
    let (want, got) = (norm(&edited), norm(&again));
    if want != got {
        let first = want
            .iter()
            .zip(got.iter())
            .position(|(a, b)| a != b)
            .unwrap_or_else(|| want.len().min(got.len()));
        problems.push(format!(
            "{what}: re-import differs from the edited model at block {first} ({} vs {} blocks)\nwant: {:?}\ngot:  {:?}",
            want.len(),
            got.len(),
            want.get(first),
            got.get(first)
        ));
    }
    // Modeled side content survives too.
    if edited.notes.len() != again.notes.len()
        || edited.comments.len() != again.comments.len()
        || edited.changes.len() != again.changes.len()
    {
        problems.push(format!(
            "{what}: notes/comments/changes count differs after re-import"
        ));
    }
    if edited.properties != again.properties {
        problems.push(format!(
            "{what}: properties differ: {:?} vs {:?}",
            edited.properties, again.properties
        ));
    }
}

/// The definitions (element, identifying attribute) of the parts a codec merges into.
const MERGED_DEFINITIONS: &[(&str, &str, &str)] = &[
    ("word/styles.xml", "w:style", "w:styleId"),
    ("word/numbering.xml", "w:num", "w:numId"),
    ("word/numbering.xml", "w:abstractNum", "w:abstractNumId"),
    ("docProps/core.xml", "dc:title", ""),
    ("styles.xml", "style:style", "style:name"),
    ("styles.xml", "text:list-style", "style:name"),
    ("styles.xml", "style:page-layout", "style:name"),
    ("styles.xml", "style:master-page", "style:name"),
    ("meta.xml", "meta:user-defined", "meta:name"),
];

/// The values of `attr` on every `element` of an XML part (the element's text when `attr`
/// is empty).
fn attr_values(xml: &[u8], element: &str, attr: &str) -> BTreeSet<String> {
    let mut reader = quick_xml::Reader::from_reader(xml);
    let mut out = BTreeSet::new();
    let mut buf = Vec::new();
    let mut in_element = false;
    loop {
        match reader.read_event_into(&mut buf).expect("well-formed XML") {
            Event::Start(e) | Event::Empty(e) if e.name().as_ref() == element.as_bytes() => {
                in_element = attr.is_empty();
                for a in e.attributes().flatten() {
                    if a.key.as_ref() == attr.as_bytes() {
                        out.insert(String::from_utf8_lossy(&a.value).into_owned());
                    }
                }
            }
            Event::Text(t) if in_element => {
                out.insert(t.xml10_content().expect("text").into_owned());
            }
            Event::End(_) => in_element = false,
            Event::Eof => break,
            _ => {}
        }
        buf.clear();
    }
    out
}

/// Parts a codec writes itself (from the model, or merging the model into the original).
fn rewritten(name: &str) -> bool {
    const DOCX: &[&str] = &[
        "[Content_Types].xml",
        "_rels/.rels",
        "word/_rels/document.xml.rels",
        "word/document.xml",
        "word/styles.xml",
        "word/numbering.xml",
        "word/footnotes.xml",
        "word/endnotes.xml",
        "word/comments.xml",
        "docProps/core.xml",
        "docProps/app.xml",
    ];
    const ODT: &[&str] = &[
        "content.xml",
        "styles.xml",
        "meta.xml",
        "META-INF/manifest.xml",
    ];
    DOCX.contains(&name)
        || ODT.contains(&name)
        || name.starts_with("word/media/")
        || name.starts_with("Pictures/")
}

/// Parts the docx exporter legitimately rewrites under another name: none today.
const DOCX_REGENERATED: &[&str] = &[];

#[test]
fn docx_fixtures_keep_unmodeled_content_through_edit_and_export() {
    let mut problems = Vec::new();
    for fx in DOCX_FIXTURES {
        check_fixture(
            &DocxCodec,
            fx,
            "word/document.xml",
            DOCX_KINDS,
            DOCX_REGENERATED,
            &DOCX_REGIONS,
            &mut problems,
        );
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

#[test]
fn odt_fixtures_keep_unmodeled_content_through_edit_and_export() {
    let mut problems = Vec::new();
    for fx in ODT_FIXTURES {
        check_fixture(
            &OdtCodec,
            fx,
            "content.xml",
            ODT_KINDS,
            &[],
            &ODT_REGIONS,
            &mut problems,
        );
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The exported package opens as a zip whose part set is a superset of the original, so a
/// second export of the re-import is byte-stable in its part list.
#[test]
fn second_round_trip_keeps_part_set() {
    for (codec, fixtures) in [
        (&DocxCodec as &dyn FormatProvider, DOCX_FIXTURES),
        (&OdtCodec as &dyn FormatProvider, ODT_FIXTURES),
    ] {
        for fx in fixtures {
            let content = tilo_content::ContentStore::memory();
            let once = codec
                .export(
                    import(codec, fx.bytes, fx.name, &content).as_ref(),
                    &content,
                )
                .expect("export");
            let twice = codec
                .export(import(codec, &once, fx.name, &content).as_ref(), &content)
                .expect("export");
            let a: BTreeSet<String> = unzip(&once).into_keys().collect();
            let b: BTreeSet<String> = unzip(&twice).into_keys().collect();
            assert_eq!(a, b, "{}: part set drifts between round-trips", fx.name);
        }
    }
}

/// Exporting to the other office format leaves out what one codec kept verbatim: its markup
/// means nothing there, and its placeholders are not text.
#[test]
fn cross_format_export_leaves_out_the_other_formats_markup() {
    /// Fixtures, the codec they are imported with, the one exported with, its body part.
    type Case<'a> = (
        &'a [Fixture],
        &'a dyn FormatProvider,
        &'a dyn FormatProvider,
        &'a str,
    );
    let cases: [Case; 2] = [
        (DOCX_FIXTURES, &DocxCodec, &OdtCodec, "content.xml"),
        (ODT_FIXTURES, &OdtCodec, &DocxCodec, "word/document.xml"),
    ];
    for (fixtures, from, to, body_part) in cases {
        for fx in fixtures {
            let content = tilo_content::ContentStore::memory();
            let d = import(from, fx.bytes, fx.name, &content);
            let out = to.export(d.as_ref(), &content).expect("export");
            let parts = unzip(&out);
            let body = parts.get(body_part).expect("body part");
            if let Err(e) = namespace_well_formed(body) {
                panic!("{} exported across: {e}", fx.name);
            }
            assert!(
                !text_nodes(body)
                    .concat()
                    .contains(tilo_doc::schema::FIELD_PLACEHOLDER),
                "{} exported across: placeholder written as text",
                fx.name
            );
        }
    }
}
